const rows = $input.all();
if (!rows.length || !rows[0].json.agent) {
  return [{ json: { _valid: false, _msg: 'No approved Stage 1 data found. Run Stage 1 first and approve it.' } }];
}
const pos = rows.find(r => r.json.agent === 'positioning');
const narr = rows.find(r => r.json.agent === 'narrative');
return [{ json: {
  _valid: true,
  generation_run_id: $('Webhook').first().json.body.generation_run_id,
  positioning_output: pos?.json.output || null,
  narrative_output: narr?.json.output || null,
  context_json: JSON.stringify({ positioning: pos?.json.output, narrative: narr?.json.output })
} }];

