const raw = $input.first().json.choices[0].message.content;
const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
if (!parsed.positioning_gaps) throw new Error('Opportunity Agent: invalid schema — missing positioning_gaps');
return [{ json: { opportunity_output: parsed } }];

const raw = $input.first().json.choices[0].message.content;
const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
if (!parsed.differentiation_angles) throw new Error('Differentiation Agent: invalid schema — missing differentiation_angles');
return [{ json: { differentiation_output: parsed } }];

const merged = $input.first().json;
const gen_run_id = $('Webhook').first().json.body.generation_run_id;
return [{ json: {
  generation_run_id: gen_run_id,
  opportunity_output: merged.opportunity_output || null,
  differentiation_output: merged.differentiation_output || null
} }];
